create type public.post_status as enum ('draft', 'scheduled', 'publishing', 'published', 'failed');
create type public.platform_name as enum ('instagram', 'facebook', 'tiktok');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.social_accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, platform public.platform_name not null, platform_user_id text not null, username text, access_token text not null, refresh_token text, token_expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, platform));
create table public.media (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, storage_path text not null, file_name text not null, mime_type text not null, file_size bigint not null, created_at timestamptz not null default now());
create table public.posts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, media_id uuid references public.media(id) on delete set null, caption text not null default '', status public.post_status not null default 'draft', scheduled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.post_platforms (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, platform public.platform_name not null, status public.post_status not null default 'draft', published_at timestamptz, error_message text, unique(post_id, platform));
alter table public.profiles enable row level security; alter table public.social_accounts enable row level security; alter table public.media enable row level security; alter table public.posts enable row level security; alter table public.post_platforms enable row level security;
create policy "Profiles are owner-readable" on public.profiles for select using (auth.uid() = id); create policy "Profiles are owner-updatable" on public.profiles for update using (auth.uid() = id);
create policy "Social accounts are owner-managed" on public.social_accounts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "Media is owner-managed" on public.media for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "Posts are owner-managed" on public.posts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "Post platforms follow post owner" on public.post_platforms for all using (exists (select 1 from public.posts where posts.id = post_platforms.post_id and posts.user_id = auth.uid())) with check (exists (select 1 from public.posts where posts.id = post_platforms.post_id and posts.user_id = auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name) values (new.id, new.raw_user_meta_data ->> 'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets (id, name, public) values ('media', 'media', false) on conflict (id) do nothing;
create policy "Users manage their media objects" on storage.objects for all using (bucket_id = 'media' and (storage.foldername(name))[1] = 'users' and (storage.foldername(name))[2] = auth.uid()::text) with check (bucket_id = 'media' and (storage.foldername(name))[1] = 'users' and (storage.foldername(name))[2] = auth.uid()::text);
create table public.conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, social_account_id uuid references public.social_accounts(id) on delete cascade, platform public.platform_name not null, external_conversation_id text not null, participant_name text not null, participant_username text, participant_avatar text, last_message text not null default '', last_message_at timestamptz, unread_count integer not null default 0 check (unread_count >= 0), status text not null default 'open' check (status in ('open', 'closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(social_account_id, external_conversation_id));
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, external_message_id text, sender_type text not null check (sender_type in ('incoming', 'outgoing')), sender_name text not null, message_text text not null, media_url text, sent_at timestamptz not null, read_at timestamptz, created_at timestamptz not null default now(), unique(conversation_id, external_message_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, social_account_id uuid references public.social_accounts(id) on delete set null, platform public.platform_name, type text not null check (type in ('message', 'comment', 'mention', 'follower', 'published', 'failed', 'reminder', 'connection')), title text not null, message text not null, external_id text, is_read boolean not null default false, created_at timestamptz not null default now());
alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.notifications enable row level security;
create policy "Conversations are owner-managed" on public.conversations for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "Messages follow conversation owner" on public.messages for all using (exists (select 1 from public.conversations where conversations.id = messages.conversation_id and conversations.user_id = auth.uid())) with check (exists (select 1 from public.conversations where conversations.id = messages.conversation_id and conversations.user_id = auth.uid()));
create policy "Notifications are owner-managed" on public.notifications for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
-- Scheduled publishing should run in a trusted cron/worker with the service role, never in the browser.